prot=""
from collections import Counter
c=Counter(prot)
print("Length", len(prot))
for aa in sorted(c, key=lambda x:-c[x]):
    print(aa, c[aa], round(100*c[aa]/len(prot),1))
# molecular weight
mw={'A':71.08,'R':156.19,'N':114.10,'D':115.09,'C':103.14,'E':129.12,'Q':128.13,'G':57.05,'H':137.14,'I':113.16,'L':113.16,'K':128.17,'M':131.19,'F':147.18,'P':97.12,'S':87.08,'T':101.10,'W':186.21,'Y':163.18,'V':99.13}
print("MW approx", sum(mw[a] for a in prot)-18.02*(len(prot)-1))
# pI
pka={'D':3.65,'E':4.25,'C':8.18,'Y':10.07,'H':6.0,'K':10.53,'R':12.48}
def charge(pH):
    q=0
    # N-term and C-term
    q+=1/(1+10**(pH-9.69))
    q-=1/(1+10**(2.34-pH))
    for a in prot:
        if a in 'KRH': q+=c[a]/(1+10**(pH-pka[a]))
        if a in 'DECY': q-=c[a]/(1+10**(pka[a]-pH))
    return q
lo,hi=0,14
for _ in range(100):
    mid=(lo+hi)/2
    if charge(mid)>0: lo=mid
    else: hi=mid
print("pI approx", round((lo+hi)/2,2))
# repeated k-mers in protein
for k in [9,10,11,12]:
    seen={}
    reps=[]
    for i in range(len(prot)-k+1):
        w=prot[i:i+k]
        seen.setdefault(w,[]).append(i+1)
    for w,pos in seen.items():
        if len(pos)>1:
            reps.append((w,pos))
    print("k=",k,"repeats:",reps[:10])
